import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    m = min(a)
    indices = []
    for i in range(n):
        if a[i] == m:
            indices.append(i)
    res = min(indices[i+1] - indices[i] for i in range(len(indices)-1))
    print(res)

if __name__ == "__main__":
    solve()
"}

