import sys

def sum_digits_mod3(n):
    """Return sum of digits of n modulo 3"""
    s = 0
    while n > 0:
        s += n % 10
        n //= 10
    return s % 3


def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    count0 = count1 = count2 = 0
    for num in a:
        m = sum_digits_mod3(num)
        if m == 0:
            count0 += 1
        elif m == 1:
            count1 += 1
        else:
            count2 += 1

    # Maximum number of lucky tickets: pairs within group0 (0+0≡0), pairs between group1 and group2
    result = (count0 // 2) + min(count1, count2)
    print(result)

if __name__ == "__main__":
    solve()
"}

