import sys

def is_subsequence(s, t):
    # Check if s is a subsequence of t
    if not s:
        return True
    if not t:
        return False

    i = j = 0
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
        j += 1
    return i == len(s)

def solve_test_case(n, s1, s2, s3):
    # Try concatenating the first two strings
    candidate = s1 + s2
    if len(candidate) > 3 * n:
        # Trim to length 3n
        candidate = candidate[:3*n]

    # Check if this candidate works
    if is_subsequence(s1, candidate) and is_subsequence(s2, candidate):
        return candidate

    # Try another combination
    candidate = s1 + s3
    if len(candidate) > 3 * n:
        candidate = candidate[:3*n]

    if is_subsequence(s1, candidate) and is_subsequence(s3, candidate):
        return candidate

    # Try s2 + s3
    candidate = s2 + s3
    if len(candidate) > 3 * n:
        candidate = candidate[:3*n]

    if is_subsequence(s2, candidate) and is_subsequence(s3, candidate):
        return candidate

    # If we got here, try concatenating all three and then trimming
    candidate = s1 + s2 + s3
    if len(candidate) > 3 * n:
        candidate = candidate[:3*n]
    return candidate


t = int(sys.stdin.readline())
for _ in range(t):
    n = int(sys.stdin.readline())
    s1 = sys.stdin.readline().strip()
    s2 = sys.stdin.readline().strip()
    s3 = sys.stdin.readline().strip()

    result = solve_test_case(n, s1, s2, s3)
    print(result)
"}

