import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a_b = []
    idx = 1
    for _ in range(n):
        a = int(data[idx])
        b = int(data[idx + 1])
        a_b.append((a, b))
        idx += 2

    # Sort by a in increasing order, and then by b in increasing order
    a_b.sort(key=lambda x: (x[0], x[1]))

    last_day = -1

    for a, b in a_b:
        if b >= last_day:
            last_day = b
        else:
            last_day = a

    print(last_day)

if __name__ == "__main__":
    solve()
"}

