import math

def can_place(r, h, pos):
    # pos is a list of centers of already placed spheres
    # Return True if we can place a new sphere at position (x, y)
    # where x is in [0, r] and y is in [0, h]
    for x, y in pos:
        # Distance between centers must be at least 2r
        if math.dist((x, y), pos[-1]) < 2*r:
            return False
    return True

def max_balloons(r, h):
    # We need to fit as many spheres of radius r as possible
    # in a semicircle of radius r and walls of height h

    # Start from the bottom
    pos = []

    # Try to place spheres from bottom to top
    for i in range(1000000000):
        # Try to place at the bottom
        if can_place(r, h, [(0, r)]):
            pos.append((0, r))
        elif can_place(r, h, [(r, r)]):
            pos.append((r, r))
        elif can_place(r, h, [(r/2, r)]):
            pos.append((r/2, r))
        elif can_place(r, h, [(0, r + 1)]):
            pos.append((0, r + 1))
        elif can_place(r, h, [(r, r + 1)]):
            pos.append((r, r + 1))
        elif can_place(r, h, [(r/2, r + 1)]):
            pos.append((r/2, r + 1))
        else:
            return len(pos)

r, h = map(int, input().split())
print(max_balloons(r, h))
"}

