import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []
    for _ in range(t):
        n = int(data[idx])
        idx += 1

        # Get n integers from the array
        arr = list(map(int, data[idx:idx+n]))
        idx += n

        if all(x == arr[0] for x in arr):
            # All elements are the same
            results.append(str(n))
        else:
            if n % 2 == 0:
                results.append('0')
            else:
                results.append('1')

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()
"}

