m, n = map(int, input().split())
sequence = list(map(int, input().split()))

# Create a mapping from value to index
temp = sorted(sequence)
index_map = {val: idx for idx, val in enumerate(temp)}

# Try each element as potential first element x
for i in range(n):
    x = temp[i]

    # Try all possible differences d from 1 to m-1
    for d in range(1, m):
        if x + d > m:
            continue  # Skip if exceeds modulus

        # Check if this sequence forms an arithmetic progression modulo m
        found = True
        used = [False] * n
        count = 0

        for k in range(n):
            expected = (x + k * d) % m
            if expected in index_map:
                # Get the index in the sorted sequence
                found_idx = index_map[expected]
                if not used[found_idx]:
                    used[found_idx] = True
                    count += 1
                else:
                    found = False
                    break
            else:
                found = False
                break

        if found and count == n:
            print(x, d)
            exit()

print(-1)
