import sys
from collections import Counter

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    count = Counter()
    for _ in range(n):
        s = next(it)
        mask = 0
        for ch in s:
            mask ^= 1 << (ord(ch) - ord('a'))
        count[mask] += 1
    ans = 0
    for mask1 in count:
        c1 = count[mask1]
        ans += c1 * (c1 - 1) // 2
        # Check all 26 bits
        for bit in range(26):
            mask2 = mask1 ^ (1 << bit)
            if mask2 in count and mask2 > mask1:
                ans += c1 * count[mask2]
    print(ans)

if __name__ == '__main__':
    main()
