visited = [[False for _ in range(m)] for _ in range(n)]

lakes = []

def is_lake_cell(i, j):
    # Check if cell is water and not on border
    return i > 0 and i < n-1 and j > 0 and j < m-1 and grid[i][j] == '.'

def dfs(i, j, visited, lake_cells):
    # Mark cell as visited and add to lake
    visited[i][j] = True
    lake_cells.append((i, j))

    # Check all 4 directions
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
        ni, nj = i+dx, j+dy
        if 0 <= ni < n and 0 <= nj < m:
            if visited[ni][nj]:
                continue
            if is_lake_cell(ni, nj) and grid[ni][nj] == '.':
                dfs(ni, nj, visited, lake_cells)

# Find all lakes
temp_visited = [[False for _ in range(m)] for _ in range(n)]
for i in range(n):
    for j in range(m):
        if not temp_visited[i][j] and is_lake_cell(i, j) and grid[i][j] == '.':
            lake_cells = []
            dfs(i, j, temp_visited, lake_cells)
            if len(lake_cells) > 0:
                lakes.append(lake_cells)

# Sort lakes by size (smallest to largest)
lakes.sort(key=lambda x: len(x))

# Number of lakes to destroy
lakes_to_destroy = len(lakes) - k

# Create new grid
new_grid = []
for i in range(n):
    row = []
    for j in range(m):
        row.append(grid[i][j])
    new_grid.append(row)

# Fill the smallest lakes
for i in range(lakes_to_destroy):
    lake = lakes[i]
    for (x, y) in lake:
        new_grid[x][y] = '*'

# Print answer
print(len(lakes_to_destroy))
for row in new_grid:
    print(''.join(row))
