import math

def count_interval(a, b):
    """Count how many units of time each train wins in the interval (0, LCM(a,b)]"""
    # Find the least common multiple
    lcm = (a * b) // math.gcd(a, b)

    # Count units won by each train
    dasha_units = 0
    masha_units = 0

    # Find all the critical points where a train arrives
    # These are multiples of a and b in (0, lcm]
    times = set()
    for i in range(1, lcm // a + 1):
        times.add(i * a)
    for i in range(1, lcm // b + 1):
        times.add(i * b)

    # Add 0 as the starting point
    times.add(0)
    times.add(lcm)

    # Sort the times and iterate through intervals
    times = sorted(times)

    for i in range(1, len(times)):
        start = times[i-1]
        end = times[i]

        # In this interval, find which train arrives first
        if start == lcm:
            # At the end, use the tie-breaking rule
            if a < b:
                dasha_units += (end - start)
            else:
                masha_units += (end - start)
        else:
            # In the middle, compare next arrival times
            next_a = ((start // a) + 1) * a
            next_b = ((start // b) + 1) * b

            if next_a < next_b:
                dasha_units += (end - start)
            else:
                masha_units += (end - start)

    return dasha_units, masha_units

def solve():
    a, b = map(int, input().split())
    dasha_units, masha_units = count_interval(a, b)

    if dasha_units > masha_units:
        print("Dasha")
    elif masha_units > dasha_units:
        print("Masha")
    else:
        print("Equal")

if __name__ == "__main__":
    solve()
