import sys

def solve_bracket_sequence(n, p, t, q):
    # Check if the sequence is valid
    # Use a stack to track opening brackets
    stack = []

    # Process each element from left to right
    for i in range(n):
        if p[i] < 0:
            # This is a closing bracket
            if not stack:
                return "NO"

            # Pop the top of the stack (opening bracket)
            opening = stack.pop()

            # Check if the absolute values match
            if abs(p[i]) != opening:
                return "NO"
        else:
            # This is an opening bracket
            stack.append(p[i])

    # All brackets must be matched, stack should be empty
    if not stack:
        return "YES"
    else:
        return "NO"

def restore_sequence(n, p, t, q):
    # Build the result sequence
    x = []

    # First pass: assign all to positive
    for i in range(n):
        x.append(p[i])

    # Second pass: assign negative to specified positions
    for pos in q:
        x[pos - 1] = -x[pos - 1]

    return x

def main():
    # Read input
    n = int(sys.stdin.readline())
    p = list(map(int, sys.stdin.readline().split()))
    t, *rest = list(map(int, sys.stdin.readline().split()))
    q = rest[:t]

    # Check if sequence is valid
    result = solve_bracket_sequence(n, p, t, q)

    if result == "NO":
        print("NO")
    else:
        print("YES")
        x = restore_sequence(n, p, t, q)
        print(' '.join(map(str, x)))

if __name__ == "__main__":
    main()
