def solve():
    n = int(input())
    freq = {}  # count occurrences of each number
    papers = []

    # Read all papers and count frequencies
    total_unions = n * (n - 1) // 2
    for _ in range(total_unions):
        parts = list(map(int, input().split()))
        k = parts[0]
        numbers = parts[1:]
        papers.append(numbers)

        # Update frequency counts
        for num in numbers:
            freq[num] = freq.get(num, 0) + 1

    # If all frequencies are the same, we need to handle specially
    all_same = True
    for num, count in freq.items():
        if count != next(iter(freq.values())):
            all_same = False
            break

    if all_same:
        # All numbers appear the same number of times
        # Each set has the same size
        set_size = next(iter(freq.values()))

        # Group numbers into sets of size 'set_size'
        set_elements = []
        for i in range(n):
            set_elements.append([])

        # Assign numbers to sets
        for num, _ in freq.items():
            for i in range(n):
                if len(set_elements[i]) < set_size:
                    set_elements[i].append(num)
                    break

    else:
        # Normal case: numbers have different frequencies
        set_elements = [[] for _ in range(n)]

        # For each number, assign to a set of its frequency size
        for num, count in freq.items():
            if count <= n:
                for i in range(n):
                    if len(set_elements[i]) < count:
                        set_elements[i].append(num)
                        break

    # Print the results
    for elements in set_elements:
        print(len(elements), end=' ')
        print(' '.join(map(str, elements)))

