import sys
from collections import Counter

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count frequency of each element
    freq = Counter(a)

    # Build increasing sequence
    inc = []
    prev = -1
    for num in sorted(freq):
        if freq[num] == 0:
            continue
        if prev < num:
            inc.append(num)
            prev = num
            freq[num] -= 1
            if freq[num] == 0:
                del freq[num]

    # Build decreasing sequence
    dec = []
    prev = float('inf')
    for num in sorted(freq, reverse=True):
        if freq[num] == 0:
            continue
        if prev > num:
            dec.append(num)
            prev = num
            freq[num] -= 1
            if freq[num] == 0:
                del freq[num]

    # Check if we used all elements
    if any(freq.values()):
        print("NO")
    else:
        print("YES")
        print(len(inc))
        if inc:
            print(" ".join(map(str, inc)))
        else:
            print()
        print(len(dec))
        if dec:
            print(" ".join(map(str, dec)))
        else:
            print()

if __name__ == "__main__":
    solve()
