# Initialize a boolean array to mark covered positions
covered = [False] * len(w)

# Mark all covered positions
for s in forbidden:
    s_len = len(s)
    for i in range(len(w) - s_len + 1):
        substring = w[i:i+s_len]
        if substring.lower() == s.lower():
            # Mark positions i to i+s_len-1
            for j in range(i, i+s_len):
                covered[j] = True

# Build result
result = []
