    # Greedy approach: build subsequences
def greedy(subarray):
    freq = {}
    for x in subarray:
        freq[x] = freq.get(x, 0) + 1

    subsequences = []
    current_subseq = []

    for x in subarray:
        # Check if we can add x to current subsequence
        can_add = True
        temp_freq = freq.copy()
        temp_freq[x] -= 1

        # Build a temporary frequency dict for the current subsequence
        current_subseq_freq = {}
        for item in current_subseq:
            current_subseq_freq[item] = current_subseq_freq.get(item, 0) + 1
        current_subseq_freq[x] = current_subseq_freq.get(x, 0) + 1

        # Check if this would violate the constraint
        valid = True
        for k, v in current_subseq_freq.items():
            if v > ceil(len(current_subseq + [x]) / 2):
                valid = False
                break

        if valid:
            current_subseq.append(x)
        else:
            # Start new subsequence
            subsequences.append(current_subseq)
            current_subseq = [x]

    if current_subseq:
        subsequences.append(current_subseq)

    return len(subsequences)

    print(greedy(subarray))
