import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        c_list = [int(next(it)) for _ in range(n)]

        # Frequency array
        freq = [0] * (n + 1)
        for c in c_list:
            freq[c] += 1

        max_count = max(freq)
        min_screens = float('inf')

        # Try all screen sizes s from 1 to max_count
        for s in range(1, max_count + 1):
            total = 0
            for cnt in freq:
                if cnt == 0:
                    continue
                # Calculate ceil(cnt / s)
                total += (cnt + s - 1) // s

            if total < min_screens:
                min_screens = total

        out_lines.append(str(min_screens))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

