        odd_char = None
        for k in range(26):
            if counts[k] % 2 == 1:
                has_odd = True
                odd_char = chr(ord('a') + k)
                break

        if not has_odd:
            all_even_count += 1
        else:
            single_odd_char_count[ord(odd_char) - ord('a')] += 1

    # Calculate palindrome pairs
    result = 0

    # Case 1: Two all-even strings
    result += all_even_count * (all_even_count - 1) // 2

    # Case 2: One all-even, one single-odd
    # For each single-odd character, count pairs with all-even strings
    for i in range(26):
