import sys

def solve(m, n, a):
    if n == 1:
        return (a[0], 0)

    if n == 2:
        return (a[0], (a[1] - a[0]) % m)

    # Sort the array
    a.sort()

    # Try all possible values for d (from 1 to m-1)
    for d in range(1, m):
        # Check if elements are congruent modulo d
        x = a[0] % d

        # Check if all elements are congruent to x modulo d
        all_congruent = True
        for val in a:
            if val % d != x:
                all_congruent = False
                break
        if not all_congruent:
            continue

        # Check if the elements form the sequence x, x+d, x+2d, ...
        expected = set()
        for i in range(n):
            expected.add((x + i * d) % m)

        # Check if expected matches a
        if expected == set(a):
            # Find the starting element x (which is actually a[0] in the sorted array)
            start = a[0]
            # Find the difference d (which we already have)
            return (start, d)

    return (-1, -1)

