import sys

def is_vowel(c):
    return c in {'a', 'e', 'i', 'o', 'u'}

def has_typo(segment):
    """Check if a segment has a typo"""
    # Track blocks of consonants
    blocks = []
    current_char = None
    consonant_count = 0

    for c in segment:
        if c == current_char:
            consonant_count += 1
        else:
            if current_char is not None:
                if is_vowel(current_char):
                    # End of a consonant block
                    blocks.append((current_char, consonant_count))
                else:
                    # End of a vowel block
                    blocks.append((current_char, consonant_count))
            current_char = c
            consonant_count = 1

    if current_char is not None:
        if is_vowel(current_char):
            blocks.append((current_char, consonant_count))
        else:
            blocks.append((current_char, consonant_count))

    # Check each block
    for char, count in blocks:
        if not is_vowel(char):  # It's a consonant block
            if count >= 3:
                # Check if all characters are the same
                all_same = True
                for i in range(1, count):
                    if segment[i] != segment[0]:
                        all_same = False
                        break

                if not all_same:
                    return True

    return False

word = sys.stdin.readline().strip()

# If the word has no typo, output it directly
if not has_typo(word):
    print(word)
else:
    # Use dynamic programming to find minimum splits
    n = len(word)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    prev = [-1] * (n + 1)  # To reconstruct the solution

    for i in range(1, n + 1):
        for j in range(i):
            segment = word[j:i]
            if not has_typo(segment):
                if dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j

    # Reconstruct the solution
    result = []
    i = n
    while i > 0:
        j = prev[i]
        segment = word[j:i]
        result.append(segment)
        i = j

    result.reverse()
    print(' '.join(result))
