import sys

def find_covered_positions(w, forbidden_list):
    n = len(w)
    covered = [False] * n
    for s in forbidden_list:
        len_s = len(s)
        for i in range(n - len_s + 1):
            if w[i:i+len_s].lower() == s.lower():
                for j in range(i, i + len_s):
                    covered[j] = True
    return covered

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    forbidden_list = []
    for i in range(1, n + 1):
        forbidden_list.append(data[i].strip())
    w = data[n + 1].strip()
    lucky_letter = data[n + 2].strip()

    covered = find_covered_positions(w, forbidden_list)

    lucky_lower = lucky_letter
    lucky_upper = lucky_letter.upper()

    result = []
    for i in range(len(w)):
        char = w[i]
        if covered[i]:
            if char.isupper():
                candidate = lucky_upper
                if candidate != char:
                    result.append(candidate)
                else:
                    # cannot use lucky letter, use smallest uppercase not equal to char
                    if char != 'A':
                        result.append('A')
                    else:
                        result.append('B')
            else:
                candidate = lucky_lower
                if candidate != char:
                    result.append(candidate)
                else:
                    # cannot use lucky letter, use smallest lowercase not equal to char
                    if char != 'a':
                        result.append('a')
                    else:
                        result.append('b')
        else:
            result.append(char)

    print(''.join(result))

if __name__ == '__main__':
    solve()
