import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    a = int(data[idx]); idx += 1
    b = int(data[idx]); idx += 1
    G = gcd(a, b)

    n = int(data[idx]); idx += 1

    # Find all divisors of G
    divisors = set()
    for i in range(1, int(math.isqrt(G)) + 1):
        if G % i == 0:
            divisors.add(i)
            divisors.add(G // i)

    # Convert to sorted list
    sorted_divisors = sorted(divisors)

    for _ in range(n):
        low = int(data[idx]); idx += 1
        high = int(data[idx]); idx += 1

        # Find the largest divisor in range
        result = -1
        for d in sorted_divisors:
            if low <= d <= high:
                result = d

        print(result)

if __name__ == "__main__":
    solve()
"}

