    left, right = 0, len(divisors) - 1
    largest_divisor = -1
    while left <= right:
        mid = (left + right) // 2
        if divisors[mid] <= high:
            largest_divisor = divisors[mid]
            left = mid + 1  # Try to find a larger divisor
        else:
            right = mid - 1

    # Check if the largest divisor found is also ≥ low
    if largest_divisor >= low:
        print(largest_divisor)
    else:
        print(-1)
