def compute_digit_sum(n):
    """Compute the digit sum of n."""
    s = 0
    while n > 0:
        s += n % 10
        n //= 10
    return s

def main():
    n = int(input())
    a = list(map(int, input().split()))

    c0 = c1 = c2 = 0
    for num in a:
        s = compute_digit_sum(num)
        rem = s % 3
        if rem == 0:
            c0 += 1
        elif rem == 1:
            c1 += 1
        else:  # rem == 2
            c2 += 1

    # max pairs = min(c1, c2) + c0 // 2
    print(min(c1, c2) + c0 // 2)

if __name__ == "__main__":
    main()
"}

