import sys

def solve(s):
    if len(s) == 0:
        return ''

    # If the string is already simple, return it
    if all(s[i] != s[i+1] for i in range(len(s)-1)):
        return s

    result = list(s)

    # Traverse from left to right
    for i in range(1, len(result)):
        # If current character is the same as previous, we need to change it
        if result[i] == result[i-1]:
            # Find a character that is different from both previous and next
            # We can just use 'b' if possible, otherwise 'c', etc.
            # Try 'b' first
            if i == 0 or result[i-1] != 'b':
                if i == len(result)-1 or result[i+1] != 'b':
                    result[i] = 'b'
                else:
                    # Try 'c'
                    result[i] = 'c'
            else:
                # Try 'c'
                result[i] = 'c'

    return ''.join(result)

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    print(solve(s))
"}

