import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    # Since we draw segments n times, starting from vertex 1 and stepping by k each time
    # The number of new regions created when drawing the i-th segment (1-indexed) is:
    # - 1 if i == 1 (first segment)
    # - gcd(i, n) for other segments

    result = [0] * n
    regions = 1  # Start with just the polygon

    for i in range(1, n + 1):
        if i == 1:
            new_regions = 1
        else:
            new_regions = gcd(i, n)

        regions += new_regions
        result[i - 1] = regions

    sys.stdout.write(' '.join(map(str, result)))
    sys.stdout.write('\n')

# Helper function for gcd
import math

def gcd(a, b):
    return math.gcd(a, b)

if __name__ == '__main__':
    solve()
