n = int(input())
probabilities = [float(p) for p in input().split()]

max_prob = 0.0

# Try all subsets
for mask in range(1 << n):
    subset = [probabilities[i] for i in range(n) if (mask >> i) & 1]
    k = len(subset)

    # Calculate probability of exactly 1 success
    if k == 0:
        prob = 0.0
    elif k == 1:
        prob = subset[0]
    elif k == 2:
        prob = subset[0] + subset[1] - 2 * subset[0] * subset[1]
    else:
        prob = 0.0
        for i in range(k):
            prob += subset[i] * product(1 - subset[j] for j in range(k) if j != i)

    max_prob = max(max_prob, prob)

print(f"{max_prob:.12f}")

# Helper function for product
def product(iterable):
    result = 1.0
    for val in iterable:
        result *= val
    return result
