import sys

def solve():
    n, *rest = map(int, sys.stdin.read().split())
    a = rest[:n]

    # Store first occurrence of each sum
    first_occurrence = {}

    # Try all pairs (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            s = a[i] + a[j]
            if s in first_occurrence:
