                # Check if we can pick four distinct indices
                if i != prev_i and i != prev_j and j != prev_i and j != prev_j:
                    print("YES")
                    print(prev_i + 1, prev_j + 1, i + 1, j + 1)
                    return
            else:
                first_occurrence[s] = (i, j)

    print("NO")

if __name__ == "__main__":
    solve()
