# Read input
word = input().strip()

# Define vowels
vowels = {'a', 'e', 'i', 'o', 'u'}

# Check if a word has a typo
def has_typo(word):
    """Check if a word has a typo.
    A typo happens if there is a block of 3 or more consecutive consonants
    and there are at least two different consonants in that block.
    """
    if len(word) < 3:
        return False

    # Find all blocks of consecutive consonants
    blocks = []
    current_block = []

    for c in word:
        if c in vowels:
            if current_block:
                blocks.append(current_block)
                current_block = []
        else:
            current_block.append(c)

    if current_block:
        blocks.append(current_block)

    # Check each block
    for block in blocks:
        if len(block) >= 3:
            # Check if there are at least two different consonants in this block
            unique_consonants = set(block)
            if len(unique_consonants) >= 2:
                return True

    return False

# Check if a substring has a typo
def is_valid(subword):
    """Check if a substring is valid (no typos).
    """
    return not has_typo(subword)

# Dynamic programming to find minimum spaces
# dp[i] = minimum number of spaces to split first i characters
n = len(word)
dp = [-1] * (n + 1)
dp[0] = 0

for i in range(1, n + 1):
    # Check all possible splits ending at position i
    for j in range(i - 1, -1, -1):
        if dp[j] != -1 and is_valid(word[j:i]):
            dp[i] = dp[j] + 1
            break  # We found the best (minimum) split, no need to continue

# Reconstruct the solution
if dp[n] == -1:
    print(word)
else:
    # Find the splits
    splits = []
    i = n
    while i > 0:
        for j in range(i - 1, -1, -1):
            if dp[j] + 1 == dp[i] and is_valid(word[j:i]):
                splits.append(word[j:i])
                i = j
                break

    # Join with spaces
    print(' '.join(splits[::-1]))
