import sys

def is_subsequence(s, t):
    """Check if s is a subsequence of t"""
    it = iter(t)
    return all(char in it for char in s)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        a = data[idx]
        idx += 1
        b = data[idx]
        idx += 1
        c = data[idx]
        idx += 1

        # Try all combinations to find one that works
        if is_subsequence(a, b):
            results.append(a)
        elif is_subsequence(b, a):
            results.append(b)
        elif is_subsequence(a, c):
            results.append(a)
        elif is_subsequence(c, a):
            results.append(c)
        elif is_subsequence(b, c):
            results.append(b)
        elif is_subsequence(c, b):
            results.append(c)
        else:
            # If none of the strings are a subsequence of another,
            # we need to create a new string
            # Output a concatenated with the first character of b
            results.append(a + b[0])

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

