for x1 in range(1, k1 + 1):
    for x2 in range(1, k2 + 1):
        for x3 in range(1, k3 + 1):
            # Check coverage for all times up to a bound
            # We need to check if coverage continues indefinitely
            # After LCM(k1,k2,k3) + max_k, the pattern repeats, so we just need to check continuity
            bound = LCM(k1, k2, k3) + max_k
            covered = [False] * (bound + 1)

            # Calculate LCM
            lcm = k1
            for k in [k2, k3]:
                lcm = lcm * k // GCD(lcm, k)

            # Check coverage
            for t in range(1, bound + 1):
                covered[t] = ((t - x1) % k1 == 0) or ((t - x2) % k2 == 0) or ((t - x3) % k3 == 0)

            # Check if coverage is continuous from some point
            for start in range(1, bound):
                is_continuous = True
                for i in range(start, start + max_k + 1):
                    if not covered[i]:
                        is_continuous = False
                        break
                if is_continuous:
                    found = True
                    break
            if found:
                break
        if found:
            break
    if found:
        break

print("YES" if found else "NO")
