        mask = 0
        for c in s:
            idx = ord(c) - ord('a')  # 0 for 'a', 1 for 'b', ..., 25 for 'z'
            mask ^= (1 << idx)  # XOR toggles the bit for this character
        freq[mask] = freq.get(mask, 0) + 1

    # Count the number of palindrome pairs (unordered, i != j)
    count = 0

    # Count for pairs (i, j) where i != j
