import math

def lcm(a, b):
    return a * b // math.gcd(a, b)

def solve():
    a, b = map(int, input().split())

    # Find LCM of a and b
    L = lcm(a, b)

    # Count how many times Dasha and Masha's trains arrive in [0, L)
    count_dasha = 0
    count_masha = 0

    i = 1
    j = 1

    while True:
        dasha_time = i * a
        masha_time = j * b

        if dasha_time >= L:
            break
        if masha_time >= L:
            break

        start = max(dasha_time, masha_time)

