import sys

def solve():
    # Read input
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    forbidden = data[1:n+1]
    w = data[n+1].strip()
    lucky_letter = data[n+2].strip()

    # Mark positions that need to be replaced
    length = len(w)
    replaced = [False] * length

    # Find all occurrences of forbidden substrings
    for substr in forbidden:
        substr_len = len(substr)
        for i in range(length - substr_len + 1):
            if w[i:i+substr_len].lower() == substr.lower():
                for j in range(i, i + substr_len):
                    replaced[j] = True

    # Generate result
    result = []
    for i in range(length):
        if replaced[i]:
            original = w[i]
            if original.lower() != lucky_letter:
                # Can use lucky letter
                if original.isupper():
                    result.append(lucky_letter.upper())
                else:
                    result.append(lucky_letter.lower())
            else:
                # Cannot use lucky letter, use smallest possible
                if original.isupper():
                    result.append('A')  # smallest uppercase letter that is not lucky_letter
                else:
                    result.append('a')  # smallest lowercase letter that is not lucky_letter
        else:
            result.append(w[i])

    print(''.join(result))

if __name__ == "__main__":
    solve()
