from math import gcd

a, b = map(int, input().split())

def lcm(x, y):
    return x * y // gcd(x, y)

# The schedule is periodic with period = LCM(a, b)
period = lcm(a, b)

dasha_count = 0
masha_count = 0

def next_train(t, interval):
    # Returns the time of the next train after time t
    return ((t + interval - 1) // interval) * interval

for t in range(period):
    next_dasha = next_train(t, a)
    next_masha = next_train(t, b)

    if next_dasha < next_masha:
        dasha_count += 1
    elif next_masha < next_dasha:
        masha_count += 1
    else:
        # Tie! Vasya goes to the direction with the lower frequency (larger interval)
        if a > b:
            dasha_count += 1
        else:
            masha_count += 1

if dasha_count > masha_count:
    print("Dasha")
elif masha_count > dasha_count:
    print("Masha")
else:
    print("Equal")
