def cross_product(p1, p2, p3):
    """Calculate cross product of vectors (p2-p1) and (p3-p1)"""
    return (p2[0] - p1[0])*(p3[1] - p1[1]) - (p2[1] - p1[1])*(p3[0] - p1[0])

def is_point_inside_triangle(p, t):
    """Check if point p is inside triangle t"""
    # Check if point is on the edge
    for i in range(3):
        v1 = t[(i+1)%3]
        v2 = t[(i+2)%3]
        if cross_product(p, v1, v2) == 0:
            # Point is on edge, but we treat this as inside for simplicity
            return True

    # Check if point is strictly inside using barycentric coordinates
    # If cross product signs are consistent
    signs = []
    for i in range(3):
        v1 = t[(i+1)%3]
        v2 = t[(i+2)%3]
        cross = cross_product(p, v1, v2)
        signs.append(cross > 0)

    return all(signs) or all(not s for s in signs)

def is_point_inside_union(p, triangles):
    """Check if point p is inside the union of given triangles"""
    for t in triangles:
        if is_point_inside_triangle(p, t):
            return True

    return False

