            mid_y = (v1[1] + v2[1]) / 2.0

            # Check if midpoint is inside union of other triangles
            inside_union = is_point_inside_union(
                (mid_x, mid_y), 
                triangles[:i] + triangles[i+1:] 
            )

            if not inside_union:
                # Add the full length of the side to perimeter
                total_perimeter += side_length(v1, v2)

    print(total_perimeter)

