        # now i is first >= a or len(packs)
        if i == 0:
            dist = packs[0] - a
        elif i == len(packs):
            dist = a - packs[-1]
        else:
            dist = min(a - packs[i-1], packs[i] - a)
        max_dist = max(max_dist, dist)

    print(max_dist)

