from collections import deque

def solve():
    n, m, k = map(int, input().split())
    grid = [list(input()) for _ in range(n)]

    # Find all lakes
    visited = [[False for _ in range(m)] for _ in range(n)]
    lakes = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # Start BFS to find this region
                queue = deque([(i, j)])
                visited[i][j] = True
                lake_cells = []

                while queue:
                    x, y = queue.popleft()
                    lake_cells.append((x, y))

                    # Check all 4 directions
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                queue.append((nx, ny))

                # Check if this region touches the border
                touches_border = False
                for x, y in lake_cells:
                    if x == 0 or x == n-1 or y == 0 or y == m-1:
                        touches_border = True
                        break

                if not touches_border:
                    lakes.append(lake_cells)

    # Sort lakes by size (smallest first)
    lakes.sort(key=lambda x: len(x))

    # Fill the smallest (n-k) lakes
    for i in range(len(lakes) - k):
        lake = lakes[i]
        for x, y in lake:
            grid[x][y] = '*'

    # Output
    print(len(lakes) - k)
    for row in grid:
        print(''.join(row))

# Run the solution
solve()
