    water_regions = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # Start BFS to find this water region
                queue = deque([(i, j)])
                visited[i][j] = True
                region = []

                while queue:
                    x, y = queue.popleft()
                    region.append((x, y))

                    # Check all 4 directions
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                queue.append((nx, ny))

                # Add this region to water_regions
                water_regions.append(region)

    # Now find which water regions are lakes (don't touch the border)
    lakes = []

    for region in water_regions:
        touches_border = False
        for x, y in region:
            if x == 0 or x == n-1 or y == 0 or y == m-1:
                touches_border = True
                break

        if not touches_border:
            lakes.append(region)

    # Sort lakes by size (smallest first)
    lakes.sort(key=lambda x: len(x))

    # Fill the smallest (len(lakes) - k) lakes
    for i in range(len(lakes) - k):
        lake = lakes[i]
        for x, y in lake:
            grid[x][y] = '*'

    # Output
    print(len(lakes) - k)
    for row in grid:
        print(''.join(row))

