import sys

def solve(a, b, h, w, n, extensions):
    # Check if we can already place the rectangle
    if h * w >= a * b:
        return 0

    # If we can't place the rectangle even with all extensions, return -1
    if n == 0:
        return -1

    # Sort extensions in descending order
    extensions.sort(reverse=True)

    # Try all possible numbers of extensions to use
    for k in range(1, n + 1):
        # Try all ways to split k extensions between the two dimensions
        # i extensions on first dimension, k-i on second
        for i in range(0, k + 1):
            # Check if we can assign i extensions to one dimension and k-i to the other
            if i == 0:
                product1 = 1
                product2 = 1
                for j in range(k):
                    product2 *= extensions[j]
            elif i == k:
                product1 = 1
                product2 = 1
                for j in range(k):
                    product1 *= extensions[j]
            else:
                product1 = 1
                product2 = 1
                for j in range(i):
                    product1 *= extensions[j]
                for j in range(i, k):
                    product2 *= extensions[j]

            # Check if this works
            if h * product1 >= a and w * product2 >= b:
                return k
            if h * product1 >= b and w * product2 >= a:
                return k

    return -1

