    """Check if after some point, all numbers are covered"""
    # For large enough numbers, we only care about residues
    # We'll check up to some limit to be safe

    # Instead of checking every number, we can use the fact that if we can cover all residues modulo d
    # where d is a common divisor of all periods, we can cover all numbers eventually

    d = math.gcd(k1, math.gcd(k2, k3))  # Common divisor

    # Check if all residues modulo d can be covered
    covered_residues = set()
    for i in range(d):
