def is_definitely_working(s):

    # For a character to definitely work, it must appear at an even position
    # (0-indexed) AND there should be no previous occurrence of that character
    definitely_working = []

    for i in range(len(s)):
        c = s[i]

        # Check if position is even (0-indexed)
        if i % 2 == 0:
            # Check if there's any previous occurrence of c
            found = False
            for j in range(i):
                if s[j] == c:
                    found = True
                    break

            if not found:
                definitely_working.append(c)

    definitely_working.sort()
    return ''.join(definitely_working)

