import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    s = []
    for _ in range(n):
        si = int(next(it))
        # ignore xi
        s.append(si)

    # LIS non-decreasing
    def lis(arr):
        import bisect
        dp = []  # tails of increasing subsequences of different lengths
        for num in arr:
            idx = bisect.bisect_right(dp, num)
            if idx == len(dp):
                dp.append(num)
            else:
                dp[idx] = num
        return len(dp)

    ans = n - lis(s)
    print(ans)

if __name__ == "__main__":
    solve()
"}

