import math

def get_divisors(g):
    """Get all divisors of g in sorted order"""
    divisors = []
    for i in range(1, int(math.isqrt(g)) + 1):
        if g % i == 0:
            divisors.append(i)
            if i != g // i:
                divisors.append(g // i)
    return sorted(divisors, reverse=True)

def solve():
    a, b = map(int, input().split())
    n = int(input())

    g = math.gcd(a, b)
    divisors = get_divisors(g)

    for _ in range(n):
        low, high = map(int, input().split())
        # Find greatest divisor in [low, high]
        result = -1
        for d in divisors:
            if low <= d <= high:
                result = d
                break
        print(result)

solve()
